s2c12_intento":true,"s2c12_contexto":false,"s2c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s2c12_intento":true,"s2c12_contexto":false,"s2c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s2c12_intento":true,"s2c12_contexto":true,"s2c12_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s2c12_intento":true,"s2c12_contexto":true,"s2c12_violacion":true},"esperado":true}]}]'::jsonb) LOOP
   cd:=p->>'codigo';
   v:=lf_ops.nucleo_regla_proponer_v1(p,false);
   IF v->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (v->>'bloqueantes')::int<>0
   THEN RAISE EXCEPTION 'S2_PREFLIGHT_REJECT % %',cd,v; END IF;
   v:=lf_ops.nucleo_regla_proponer_v1(p,true);
   IF v->>'resultado'<>'CANDIDATA' OR (v->>'version')::int<>1
   THEN RAISE EXCEPTION 'S2_CREATE_FAILED % %',cd,v; END IF;
   IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   OR (SELECT count(DISTINCT entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   THEN RAISE EXCEPTION 'S2_VECTORS_INVALID %',cd; END IF;
   hp:=lf_ops.nucleo_hash_paquete_v1(cd,1);
   IF length(hp)<>64 THEN RAISE EXCEPTION 'S2_HASH_INVALID %',cd; END IF;
   e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
   IF e->>'decision'='AUTO' OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)<>'CANDIDATA'
   THEN RAISE EXCEPTION 'S2_UNAUTHORIZED_AUTO % %',cd,e; END IF;
   RAISE NOTICE 'S2_VECTOR_CANDIDATA % legacy=% hash=% decision=%',cd,p->'origen'->>'ref',hp,e->>'decision';
   n:=n+1;
 END LOOP;
 IF n<>12 OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S2-C%')<>0
  OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>12
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 THEN RAISE EXCEPTION 'S2_FINAL_INVALID'; END IF;
 RAISE NOTICE 'S2_TANDA_PASS candidatas=12 pruebas=96 juicios=0 publicaciones=0';
END $create$;
COMMIT;
